targets.expr:
sum by (source, target) (
  label_replace(
    label_replace(
      sum by (client, server) (
        rate(traces_service_graph_request_total{client!="", server!=""}[$__rate_interval])
      ),
      "source", "$1", "client", "(.*)"
    ),
    "target", "$1", "server", "(.*)"
  )
)

